# awk-implementation-independent extraction (cdt-005): gawk and mawk differ on
# dynamic-regex backslash handling, and an unescaped '.' in the version string is a
# regex wildcard. Use an exact-prefix string match in node, and FAIL LOUDLY if the
# section is missing rather than silently shipping a barren "See CHANGELOG.md" body.
node -e '
  const { readFileSync, writeFileSync } = require("fs");
  const version = (process.env.REF_NAME || "").replace(/^v/, "");
  const target = "## [" + version + "]";
  const lines = readFileSync("CHANGELOG.md", "utf8").split(/\r?\n/);
  if (!lines.some((l) => l.indexOf(target) === 0)) {
    console.error("::error::No CHANGELOG section found for " + target);
    process.exit(1);
  }
  let capture = false; const out = [];
  for (const line of lines) {
    if (/^## \[/.test(line)) { if (capture) break; capture = line.indexOf(target) === 0; continue; }
    if (capture) out.push(line);
  }
  const notes = out.join("\n").trim();
  writeFileSync("RELEASE_NOTES.md", (notes || "See CHANGELOG.md") + "\n");
'
